// Ventana: solo se miran los envíos de HOY.
const ahora = new Date();
const medianoche = Math.floor(
  new Date(ahora.getFullYear(), ahora.getMonth(), ahora.getDate()).getTime() / 1000);

// Las conversaciones vienen ordenadas por actividad reciente, así que las de
// hoy están en las primeras páginas. 4 páginas = 100 conversaciones.
const salida = [];
for (let p = 1; p <= 4; p++) salida.push({ json: { page: p, hoy_medianoche: medianoche } });
return salida;

const t0 = $('Ventana de hoy').first().json.hoy_medianoche;
const vistos = new Set();
const salida = [];
for (const item of $input.all()) {
  const pay = (item.json && item.json.data && item.json.data.payload) || [];
  for (const c of pay) {
    if ((c.last_activity_at || 0) >= t0 && !vistos.has(c.id)) {
      vistos.add(c.id);
      salida.push({ json: { conversation_id: c.id } });
    }
  }
}
return salida;

const t0 = $('Ventana de hoy').first().json.hoy_medianoche;
const ahora = Math.floor(Date.now() / 1000);

const IMG = 'https://chatwoot-rincondelosgenios.serversvisionarius.com/rails/active_storage/blobs/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBMQT09IiwiZXhwIjpudWxsLCJwdXIiOiJibG9iX2lkIn19--b572b6dd47abf2301a3b30ccfd51603c6f194536/cumple.jpeg';
const MAX_INTENTOS = 3;    // como mucho 3 envíos por clienta y día
const MARGEN_SEG   = 300;  // no tocar un fallo de hace menos de 5 min

// Errores que NO se reintentan: son del destinatario o de la plantilla, y
// reintentar no cambiaría nada. Todo lo demás (caídas, 131053 de imagen,
// errores genéricos de plataforma) sí se reintenta.
const PERMANENTES = /^(131026|131047|131049|131050|131051|130472|132\d+|133\d+)/;

const salida = [];
for (const item of $input.all()) {
  const msgs = (item.json && item.json.payload) || [];

  const plantillas = msgs.filter(m =>
    m.message_type === 1 && !m.private && m.created_at >= t0 &&
    String(m.content || '').includes('Se acerca el cumple de'));
  if (!plantillas.length) continue;

  // Se agrupa por cupón: cada cupón es una clienta concreta de hoy.
  const porCupon = {};
  for (const m of plantillas) {
    const c = String(m.content || '').match(/Código de descuento:\s*([A-Z0-9]{4,15})/);
    if (!c) continue;
    if (!porCupon[c[1]]) porCupon[c[1]] = [];
    porCupon[c[1]].push(m);
  }

  for (const cupon of Object.keys(porCupon)) {
    const lista = porCupon[cupon].sort((a, b) => b.created_at - a.created_at);

    // Si ya hay un envío vivo con ese cupón, no se duplica. 'sent' cuenta como
    // vivo: puede estar pendiente de que la clienta encienda el móvil.
    if (lista.some(m => ['sent', 'delivered', 'read'].includes(m.status))) continue;
    if (lista.length >= MAX_INTENTOS) continue;

    const ultimo = lista[0];
    if (ultimo.status !== 'failed') continue;
    if (ahora - ultimo.created_at < MARGEN_SEG) continue;

    const err = String((ultimo.content_attributes || {}).external_error || '');
    if (PERMANENTES.test(err)) continue;

    const txt   = String(ultimo.content || '');
    const padre = (txt.match(/^Hola (.+?),/) || [])[1];
    const hijo  = (txt.match(/Se acerca el cumple de (.+?)\n/) || [])[1];
    if (!padre || !hijo) continue;

    salida.push({ json: {
      conversation_id: ultimo.conversation_id,
      cupon, padre, hijo,
      intento: lista.length + 1,
      error_previo: err || '(sin detalle)',
      cw_body: {
        content: txt,
        message_type: 'outgoing',
        private: false,
        template_params: {
          name: 'descuento_2', language: 'es',
          processed_params: {
            header:  { media_url: IMG, media_type: 'image' },
            body:    { '1': padre, '2': hijo, '3': cupon },
            buttons: [ { type: 'hueco' }, { type: 'copy_code', parameter: cupon } ]
          }
        }
      }
    }});
  }
}
return salida;

// Deja constancia de lo reintentado para poder verlo en el historial de n8n.
const det = $('Detecta fallos reintentables').all();
const res = $input.all();
const filas = det.map((d, i) => ({
  clienta: d.json.padre, peque: d.json.hijo, cupon: d.json.cupon,
  intento: d.json.intento, error_previo: d.json.error_previo,
  nuevo_mensaje: (res[i] && res[i].json && res[i].json.id) || null,
}));
return [{ json: { reintentados: filas.length, detalle: filas } }];
